class TrieNode:
    def __init__(self):
        self.children = {}                  # 字符 -> 子节点
        self.pass_ = 0                      # 经过这个节点的单词数
        self.end = False                    # 有没有单词在这里结束

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:     # 没有这条路就新建
                node.children[ch] = TrieNode()
            node = node.children[ch]
            node.pass_ += 1
        node.end = True                     # 标记单词在这里结束

    def find(self, s: str) -> Optional[TrieNode]:
        node = self.root
        for ch in s:
            if ch not in node.children:     # 走不下去了
                return None
            node = node.children[ch]
        return node

    def search(self, word: str) -> bool:
        node = self.find(word)
        return node is not None and node.end    # 还要看结束标记

    def countPrefix(self, prefix: str) -> int:
        node = self.find(prefix)
        return node.pass_ if node else 0

