class Solution:
    def replaceWords(self, dictionary: List[str], sentence: str) -> str:
        root = {}                               # 嵌套的字典当节点，"#" 表示有词根在这里结束
        for w in dictionary:
            node = root
            for ch in w:
                node = node.setdefault(ch, {})
            node["#"] = True
        res = []
        for word in sentence.split():
            node, cut = root, word
            for i, ch in enumerate(word):
                if ch not in node:              # 路断了：没有词根是它的前缀
                    break
                node = node[ch]
                if "#" in node:                 # 第一次碰到结束标记：最短的词根
                    cut = word[:i + 1]
                    break
            res.append(cut)
        return " ".join(res)

