public:
    string replaceWords(vector<string>& dictionary, string sentence) {
        Node* root = new Node();
        for (auto& w : dictionary) {
            Node* node = root;
            for (char ch : w) {
                if (!node->children[ch - 'a']) {
                    node->children[ch - 'a'] = new Node();
                }
                node = node->children[ch - 'a'];
            }
            node->end = true;
        }
        string res;
        stringstream ss(sentence);
        for (string word; ss >> word;) {
            Node* node = root;
            string cut = word;
            for (int i = 0; i < (int)word.size(); i++) {
                node = node->children[word[i] - 'a'];   // 路断了就是没有词根是它的前缀
                if (!node) {
                    break;
                }
                if (node->end) {                    // 第一次碰到结束标记：最短的词根
                    cut = word.substr(0, i + 1);
                    break;
                }
            }
            res += (res.empty() ? "" : " ") + cut;
        }
        return res;
    }
};

