func replaceWords(dictionary []string, sentence string) string {
	root := &rootNode{}
	for _, w := range dictionary {
		node := root
		for _, ch := range w {
			if node.children[ch-'a'] == nil {
				node.children[ch-'a'] = &rootNode{}
			}
			node = node.children[ch-'a']
		}
		node.end = true
	}
	res := []string{}
	for _, word := range strings.Fields(sentence) {
		node, cut := root, word
		for i := 0; i < len(word); i++ {
			node = node.children[word[i]-'a'] // 路断了就是没有词根是它的前缀
			if node == nil {
				break
			}
			if node.end { // 第一次碰到结束标记：最短的词根
				cut = word[:i+1]
				break
			}
		}
		res = append(res, cut)
	}
	return strings.Join(res, " ")
}

