interface RootNode {
    [ch: string]: RootNode | undefined;
}

function replaceWords(dictionary: string[], sentence: string): string {
    const root: RootNode = {};                  // 嵌套的对象当节点，"#" 表示有词根在这里结束
    for (const w of dictionary) {
        let node = root;
        for (const ch of w) {
            node = node[ch] ??= {};
        }
        node["#"] = {};
    }
    const res: string[] = [];
    for (const word of sentence.split(" ")) {
        let node: RootNode | undefined = root, cut = word;
        for (let i = 0; i < word.length; i++) {
            node = node[word[i]];               // 路断了就是没有词根是它的前缀
            if (!node) {
                break;
            }
            if (node["#"]) {                    // 第一次碰到结束标记：最短的词根
                cut = word.slice(0, i + 1);
                break;
            }
        }
        res.push(cut);
    }
    return res.join(" ");
}

